obligation_text:
ASSUME NEW CONSTANT Nodes,
       NEW CONSTANT Succ,
       NEW CONSTANT S \in SUBSET Nodes,
       NEW CONSTANT T \in SUBSET Nodes,
       \A n \in S : Succ[n] \subseteq S \cup T ,
       ASSUME NEW CONSTANT n \in {n \in Nodes :
                                    \E m \in S : ExistsPath(m, n)}
       PROVE  n \in S \cup {n_1 \in Nodes : \E m \in T : ExistsPath(m, n_1)} 
PROVE  {n \in Nodes : \E m \in S \cup T : ExistsPath(m, n)}
       \subseteq S \cup {n \in Nodes : \E m \in T : ExistsPath(m, n)}

ASSUME NEW CONSTANT Nodes,
       NEW CONSTANT Succ,
       NEW CONSTANT S \in SUBSET Nodes,
       NEW CONSTANT n \in S,
       {n_1 \in Nodes : \E m \in Succ[n] : ExistsPath(m, n_1)}
       \subseteq {n_1 \in Nodes : \E m \in S : ExistsPath(m, n_1)} 
PROVE  {n_1 \in Nodes : \E m \in S \cup Succ[n] : ExistsPath(m, n_1)}
       \subseteq {n_1 \in Nodes : \E m \in S : ExistsPath(m, n_1)}

ASSUME NEW CONSTANT Nodes,
       NEW CONSTANT Succ,
       SuccAssump == Succ \in [Nodes -> SUBSET Nodes],
       ExistsPath(m, n) == \E p \in Seq(Nodes) : IsPathFromTo(p, m, n),
       ReachableFrom(S) == {n \in Nodes : \E m \in S : ExistsPath(m, n)}
PROVE  ReachableFrom({}) = {}

ASSUME NEW CONSTANT S,
       NEW CONSTANT seq \in Seq(S),
       ASSUME NEW CONSTANT x \in Range(seq)
       PROVE  Cardinality({i \in DOMAIN seq : seq[i] = x}) \in Nat \ {0} 
PROVE  ASSUME NEW CONSTANT x \in Range(seq)
       PROVE  Cardinality({i \in DOMAIN seq : seq[i] = x}) \in Nat \ {0}

ASSUME NEW CONSTANT S,
       NEW CONSTANT seq \in Seq(S),
       NEW CONSTANT x \in Range(seq),
       {i \in DOMAIN seq : seq[i] = x} # {} 
PROVE  {i \in DOMAIN seq : seq[i] = x} # {}

ASSUME ASSUME NEW CONSTANT S
       PROVE  ExistsBijection(1..0, S) <=> S = {} 
PROVE  ASSUME NEW CONSTANT S
       PROVE  ExistsBijection(1..0, S) <=> S = {}

ASSUME NEW CONSTANT S,
       NEW CONSTANT T,
       NEW CONSTANT f \in Injection(S, T),
       IsFiniteSet(T) ,
       S = {} 
PROVE  S = {}

ASSUME NEW CONSTANT S,
       NEW CONSTANT T,
       NEW CONSTANT f \in Injection(S, T),
       IsFiniteSet(T) ,
       S # {} 
PROVE  S # {}

ASSUME NEW CONSTANT S,
       NEW CONSTANT s \in Seq(S),
       NEW CONSTANT m \in 1..Len(s),
       NEW CONSTANT n \in 1..Len(s)
PROVE  {SubSeq(s, m, n)[x] : x \in DOMAIN SubSeq(s, m, n)}
       \subseteq {s[x] : x \in DOMAIN s}

ASSUME NEW CONSTANT S,
       NEW CONSTANT s \in Seq(S),
       s # <<>> 
PROVE  /\ Head(s) \in S
       /\ Head(s) \in {s[x] : x \in DOMAIN s}
       /\ Tail(s) \in Seq(S)
       /\ Len(Tail(s)) = Len(s) - 1
       /\ \A i \in 1..Len(Tail(s)) : Tail(s)[i] = s[i + 1]
       /\ {Tail(s)[x] : x \in DOMAIN Tail(s)}
          \subseteq {s[x] : x \in DOMAIN s}

ASSUME NEW CONSTANT S,
       NEW CONSTANT s1 \in Seq(S),
       NEW CONSTANT s2 \in Seq(S)
PROVE  {s1[x] : x \in DOMAIN s1}
       \subseteq {(s1 \o s2)[x] : x \in DOMAIN s1 \o s2}

ASSUME NEW CONSTANT S,
       NEW CONSTANT s1 \in Seq(S),
       NEW CONSTANT s2 \in Seq(S)
PROVE  {(s1 \o s2)[x] : x \in DOMAIN s1 \o s2}
       \subseteq {s1[x] : x \in DOMAIN s1} \cup {s2[x] : x \in DOMAIN s2}

ASSUME NEW CONSTANT Def(_, _),
       NEW CONSTANT R,
       NEW CONSTANT S,
       NEW CONSTANT f,
       IsWellFoundedOn(R, S) ,
       \A i, j, k \in S : <<i, j>> \in R /\ <<j, k>> \in R => <<i, k>> \in R ,
       WFDefOn(R, S, Def) ,
       OpDefinesFcn(f, S, Def) ,
       NEW CONSTANT x \in S,
       TRUE 
PROVE  /\ {x} \cup {y \in S : <<y, x>> \in R}
          = {x}
            \cup (UNION {{y} \cup {y_1 \in S : <<y_1, y>> \in R} :
                           y \in {y \in S : <<y, x>> \in R}})
       /\ x \in {x} \cup {y \in S : <<y, x>> \in R}
          /\ {y \in S : <<y, x>> \in R}
             \subseteq {x} \cup {y \in S : <<y, x>> \in R}
       /\ \A y \in {x} \cup {y \in S : <<y, x>> \in R} :
             {y_1 \in S : <<y_1, y>> \in R}
             \subseteq {x} \cup {y_1 \in S : <<y_1, x>> \in R}
       /\ \A y \in {x} \cup {y \in S : <<y, x>> \in R} :
             {y} \cup {y_1 \in S : <<y_1, y>> \in R}
             \subseteq {x} \cup {y_1 \in S : <<y_1, x>> \in R}
       /\ {x} \cup {y \in S : <<y, x>> \in R} \subseteq S
